const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v11H3Z"/><path d="M9 21v-8h6v8"/>',upload:'<path d="M12 16V3m-5 5 5-5 5 5M3 15v6h18v-6"/>',book:'<rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/>',chart:'<path d="M3 3v18h18M7 16l5-6 4 3 5-8"/>',bell:'<path d="M5 17h14l-2-3V8a5 5 0 0 0-10 0v6ZM10 21h4"/>',people:'<circle cx="9" cy="7" r="3"/><path d="M3 21v-5a6 6 0 0 1 12 0v5m1-17a3 3 0 0 1 0 6m2 3a5 5 0 0 1 3 5v3"/>',target:'<circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="5"/><circle cx="12" cy="12" r="1"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 8a3 3 0 1 1 4 3v3m-1 3h.01"/>'};
const icon=n=>`<svg width="19" height="19" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[n]||icons.book}</svg>`;
const initial=()=>({submitted:false,ocr:false,graded:false,released:false,gap:'suggested',flag:'suggested',followup:false,followupReviewedAt:0,feedback:'You have made a good start! When comparing fractions, use equal-sized pieces. Try drawing two fraction bars before choosing the larger fraction.',practice:'Draw and compare 1/3 and 1/4, then 2/5 and 2/3. Complete five fraction-bar practice questions.',marks:[1,5,5],answers:['1/8 is greater than 1/4 because 8 is bigger.','3 × 4 = 12','1/2 + 1/2 = 1'],intervention:null,notificationsRead:false,subject:'Mathematics',language:'English',filename:'',outcome:'Ongoing',gapEvidenceReviewed:false,archived:[],notifications:[],assessmentId:'assessment-1',assessmentTitle:'Mathematics · Fractions',assessmentDate:'',releasedAt:0,filetype:'sample'});
let state;try{state=JSON.parse(localStorage.getItem('uxplosion-v2'))||initial()}catch{state=initial()}state.archived=Array.isArray(state.archived)?state.archived:[];state.assessmentTitle=state.assessmentTitle||'Mathematics · Fractions';state.assessmentId=state.assessmentId||'assessment-1';state.notifications=Array.isArray(state.notifications)?state.notifications:[];if(state.released&&!state.notifications.some(n=>n.assessmentId===state.assessmentId)){state.notifications.push({id:'notice-'+state.assessmentId,assessmentId:state.assessmentId,title:state.assessmentTitle,date:state.assessmentDate||'Earlier release',read:!!state.notificationsRead});}state.notificationsRead=undefined;let role='student',page='dashboard',selected='current',previewUrl='',uploadStep=1,tab='gap';
const historicalAssessments=[
 {title:'Quiz 1 · Fractions',score:8.25,total:15,date:'21 October 2026',id:'2'},
 {title:'Quiz 2 · Fractions',score:9,total:15,date:'28 October 2026',id:'1'},
 {title:'Practice 3 · Fractions',score:10.75,total:15,date:'4 November 2026',id:'0'}
];
function percentage(score,total=15){return Math.round(100*Number(score)/Number(total))}
function assessmentHistory(){
 const timestamp=x=>{const n=Date.parse(x||'');return Number.isFinite(n)?n:0};
 const items=historicalAssessments.map(x=>({...x,sortKey:timestamp(x.date)}));
 [...state.archived].reverse().forEach((x,i)=>items.push({title:x.title,score:x.marks.reduce((a,b)=>a+Number(b),0),total:15,date:x.date,id:'archive-'+(state.archived.length-i-1),sortKey:x.releasedAt||timestamp(x.date)}));
 if(state.submitted&&state.released)items.push({title:state.assessmentTitle||'Mathematics · Fractions',score:state.marks.reduce((a,b)=>a+Number(b),0),total:15,date:state.assessmentDate,id:'current',sortKey:state.releasedAt||timestamp(state.assessmentDate)});
 if(state.followup)items.push({title:'Follow-up · Fractions',score:gapStatus()==='Resolved'?100:gapStatus()==='Worsening'?40:90,total:100,date:'Teacher-confirmed example',id:'followup',sortKey:state.followupReviewedAt||timestamp('2026-11-10')});
 return items.sort((a,b)=>a.sortKey-b.sortKey);
}
function unreadNotifications(){return state.notifications.filter(n=>!n.read).length}
function studentFeedback(lang){return lang==='German'?{
 feedback:'Du hast einen guten Anfang gemacht! Vergleiche Brüche mit gleich großen Teilen. Zeichne zwei Bruchstreifen und überlege, welches Stück größer ist.',
 practice:'Zeichne und vergleiche 1/3 mit 1/4 und danach 2/5 mit 2/3. Löse fünf Aufgaben mit Bruchstreifen.'
 }:{feedback:initial().feedback,practice:initial().practice}}
function notificationDestination(id){if(id===state.assessmentId&&state.released)return 'current';const i=state.archived.findIndex(a=>a.assessmentId===id);return i>=0?'archive-'+i:null}
function openNotification(id){const n=state.notifications.find(n=>n.id===id);if(!n)return;const destination=notificationDestination(n.assessmentId);if(!destination){toast('This assessment is not available in the current workspace.');return;}n.read=true;save();openResult(destination)}
function save(){try{localStorage.setItem('uxplosion-v2',JSON.stringify(state))}catch{toast('Browser storage is unavailable. Keep this tab open during the demo.')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3200)}
function go(p){page=p;render();window.scrollTo(0,0)}
function switchRole(r){role=r;go('dashboard')}
const badge=(t,c='')=>`<span class="badge ${c}">${t}</span>`;
const button=(t,action,kind='',disabled=false)=>`<button class="btn ${kind}" ${disabled?'disabled':''} onclick="${action}">${t}</button>`;
function header(title,sub,action=''){return `<div class="pagehead row between"><div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`}
function card(title,body,action=''){return `<section class="card"><div class="cardhead"><h2>${title}</h2>${action}</div>${body}</section>`}
function navItem(p,t,i){return `<button class="nav ${page===p?'active':''}" onclick="go('${p}')">${icon(i)}${t}</button>`}
function render(){let student=role==='student';$('#app').innerHTML=`<aside class="sidebar"><div class="logo"><span class="mark">${icon('book')}</span><span class="brand-word"><strong>Learning</strong><span>Lab</span></span></div><div class="sublogo">YOUR LEARNING WORKSPACE</div><div class="classroom"><div class="class-number">4</div><div class="class-desc"><strong>Grade 4 · Class A</strong><small>My classroom</small></div><span class="class-check" aria-hidden="true">✓</span></div><div class="navlabel">${student?'MY LEARNING':'TEACHER WORKSPACE'}</div><nav>${navItem('dashboard','Overview','home')}${student?navItem('upload','Upload an exam','upload')+navItem('exams','My exams','book')+navItem('progress','My progress','chart')+navItem('notifications','Notifications','bell'):navItem('queue','Assessment review','book')+navItem('students','Students','people')+navItem('gaps','Learning gaps','target')+navItem('intervention','Support plans','chart')}</nav><div class="sidebar-bottom"><nav class="side-help">${navItem('guide','Help & support','help')}</nav><div class="side-profile"><div class="avatar">${student?'LM':'MS'}</div><div class="side-profile-text"><strong>${student?'Lina Mostafa':'Ms. Sarah'}</strong><small>${student?'Student · Grade 4':'Teacher · Mathematics'}</small></div></div></div></aside><header class="topbar"><div class="crumb">Workspace <span style="padding:0 12px">/</span><strong style="color:#6a657e">${student?'Student':'Teacher'} overview</strong></div><div class="topright"><div class="switch" aria-label="Demo role"><button class="${student?'on':''}" onclick="switchRole('student')">Student view</button><button class="${!student?'on':''}" onclick="switchRole('teacher')">Teacher view</button></div><button class="bell" aria-label="Open notifications" onclick="go('${student?'notifications':'queue'}')">${icon('bell')}${unreadNotifications()?'<b></b>':''}</button><div class="avatar">${student?'LM':'MS'}</div><small>${student?'Lina Mostafa':'Ms. Sarah'}<br><span style="font-size:10px">${student?'Grade 4 · Class A':'Mathematics teacher'}</span></small></div></header><main class="main">${content()}<footer class="footer"><span>UXplosion · CSEN 909 · Milestone 3</span><span>Interactive prototype · Sample students & simulated AI</span></footer></main>`}
function content(){return ({dashboard:dashboard,upload:upload,exams:exams,results:results,progress:progress,notifications:notifications,queue:queue,ocr:ocr,grading:grading,students:students,gaps:gaps,intervention:intervention,guide:guide})[page]?.()||dashboard()}
function stat(label,num,note,ico='book'){return `<div class="stat"><div class="row between"><small>${label}</small><span class="symbol">${icon(ico)}</span></div><div class="number">${num}</div><small>${note}</small></div>`}
function chart(){const items=assessmentHistory().slice(-8);return `<div class="chart" role="img" aria-label="Assessment scores: ${esc(items.map(x=>x.title+' '+percentage(x.score,x.total)+' percent').join(', '))}">${items.map(x=>`<div class="bar" style="height:${percentage(x.score,x.total)}%" title="${esc(x.title)}: ${percentage(x.score,x.total)}%"><span>${percentage(x.score,x.total)}%</span></div>`).join('')}</div><div class="chartlabels">${items.map(x=>`<span title="${esc(x.title)}">${esc(x.title.replace(' · Fractions','').replace(' · Fractions',''))}</span>`).join('')}</div><p class="muted" style="font-size:11px;margin-top:9px">Scores are calculated from released assessments${state.followup?' and the labelled simulated follow-up':''}.</p>`}
function dashboard(){let student=role==='student';return header(student?'Good morning, Lina ☀':'Your classroom, at a glance',student?'Let’s take another small step forward today.':'A clear view of your students and what needs your attention.',button(student?'+ Upload an exam':'Review assessments →',student&&state.submitted&&state.released?'startNewExam()':`go('${student?'upload':'queue'}')`))+`<div class="hero"><div><div class="eyebrow">${student?'YOUR LEARNING JOURNEY':'TEACHER-GUIDED. EVIDENCE-BASED.'}</div><h2>${student?'Small steps. Brighter understanding.':'Turn assessment into understanding.'}</h2><p>${student?'You’re building confidence, one concept at a time. Let’s see how far you’ve come.':'Review AI suggestions, connect patterns across exams, and give each learner a clear next step.'}</p>${button(student?'Explore my progress →':'Explore learning gaps →',`go('${student?'progress':'gaps'}')`,'secondary')}</div><div class="art" aria-hidden="true"><div class="sheet"><i></i><i></i><i style="width:65%"></i><div style="color:#ae99d0;font-size:30px">A⁺</div></div><div class="star">✧</div><div class="seal">✓</div></div></div><div class="stats">${student?stat('Completed assessments',String(assessmentHistory().length),'Keep your curiosity growing','book')+stat('Latest practice score',percentage(assessmentHistory().at(-1).score,assessmentHistory().at(-1).total)+'%',state.followup?'Teacher-confirmed follow-up':'Latest released assessment','chart')+stat('Topics to practice',gapStatus()==='Resolved'?'0':'1',gapStatus()==='Resolved'?'Fraction goal achieved':'Comparing fractions','target')+stat('Teacher updates',String(unreadNotifications()),unreadNotifications()?'Unread feedback available':'You’re all caught up','bell'):stat('Students in demo','1','Lina Mostafa · Grade 4','people')+stat('Awaiting review',state.submitted&&!state.released?'1':'0','OCR → grading → release','book')+stat('Tracked concepts','1','Evidence across assessments','target')+stat('Active support plans',state.intervention&&state.outcome==='Ongoing'?'1':'0','Personalized next steps','chart')}</div><div class="grid"><div>${card(student?'My recent assessments':'Assessment review',examTable(),`<button class="textbtn" onclick="go('${student?'exams':'queue'}')">View all →</button>`)}${card('Progress over time',chart())}</div><div>${card(student?'Let’s keep practicing':'Learning gaps to watch',`<div class="row between"><span class="examicon">${icon('target')}</span>${badge(gapStatus(),state.followup?'green':'orange')}</div><h3 style="margin-top:15px">Comparing fractions</h3><p class="muted" style="font-size:12px">${student?'Bigger numbers don’t always mean bigger pieces. Let’s explore together.':'The same misconception appears in two teacher-confirmed quizzes. Inspect the exact answers before taking action.'}</p><div class="progress"><span style="width:${state.followup?85:45}%"></span></div><small>${state.followup?(gapStatus()==='Resolved'?'Two follow-ups: 5 of 5 correct':gapStatus()==='Worsening'?'Follow-up: 1 of 5 correct':'Follow-up: 4 of 5 correct'):((2+(state.gap==='confirmed'?1:0)+followupCount())+' linked assessments · Teacher-confirmed history')}</small><div style="margin-top:18px">${button(student?'See my learning journey':'View supporting evidence',`go('${student?'progress':'gaps'}')`,'soft')}</div>`)}${card('A note from your teacher',`<div class="row"><div class="avatar">MS</div><div><strong>Ms. Sarah</strong><br><small>Your learning partner</small></div></div><p class="muted" style="font-size:12px">“It’s okay to find something tricky. What matters is trying a different way and asking for help.”</p>`)}</div></div>`}
function examTable(){const current=state.submitted?`<tr><td><strong>${esc(state.assessmentTitle||state.subject+' assessment')}</strong><br><small>${esc(state.assessmentDate||'Current submission')} · ${esc(state.language)}</small></td><td>${badge(state.released?'Results released':state.graded?'Feedback review':state.ocr?'Grade review':'OCR review',state.released?'green':'orange')}</td><td>${state.released?state.marks.reduce((a,b)=>a+Number(b),0)+'/15':'Not released'}</td><td><button class="textbtn" onclick="${role==='student'?"openResult('current')":"openReview()"}">${role==='student'?(state.released?'View details →':'Status →'):'Review →'}</button></td></tr>`:'';const previous=state.archived.map((x,i)=>`<tr><td><strong>${esc(x.title)}</strong><br><small>${esc(x.date)} · ${esc(x.language)}</small></td><td>${badge('Results released','green')}</td><td><strong>${x.marks.reduce((a,b)=>a+Number(b),0)}/15</strong></td><td><button class="textbtn" onclick="openResult('archive-${i}')">View details →</button></td></tr>`).join('');const historic=[['Practice 3 · Fractions','10.75/15','4 November'],['Quiz 2 · Fractions','9/15','28 October'],['Quiz 1 · Fractions','8.25/15','21 October']].map((x,i)=>`<tr><td><strong>${x[0]}</strong><br><small>${x[2]} 2026 · English</small></td><td>${badge('Results released','green')}</td><td><strong>${x[1]}</strong></td><td><button class="textbtn" onclick="openResult('${i}')">View details →</button></td></tr>`).join('');return `<div class="table-scroll"><table><thead><tr><th>ASSESSMENT</th><th>STATUS</th><th>GRADE</th><th></th></tr></thead><tbody>${current}${previous}${historic}</tbody></table></div>`}

function exams(){return header('My exams','Your work, feedback, and next steps.',button('+ Upload an exam',state.submitted&&state.released?'startNewExam()':"go('upload')"))+card('Assessment history',examTable())}
function openResult(id){selected=id;go('results')}function openReview(){go(!state.ocr?'ocr':!state.graded?'grading':'gaps')}
function steps(){return `<div class="steps">${['Upload received','OCR verified','Grades confirmed','Results released'].map((t,i)=>`<div class="step ${[state.submitted,state.ocr,state.graded,state.released][i]?'done':''}">${i+1}. ${t}</div>`).join('')}</div>`}
function upload(){return header('Upload an exam','A few simple steps, then your teacher takes it from here.')+`<div class="steps"><div class="step done">1. Exam details</div><div class="step ${uploadStep===2?'done':''}">2. Preview & submit</div><div class="step ${state.submitted?'done':''}">3. Teacher review</div></div>`+card(uploadStep===1?'Tell us about your exam':'Check your exam',state.submitted?`${steps()}<div class="notice">${state.released?'Your teacher has released your results.':'Your exam is safely submitted. Your teacher will check the extracted answers and approve your results.'}</div>${button(state.released?'View my results':'Back to overview',state.released?"openResult('current')":"go('dashboard')")}${state.released?`<div style="margin-top:14px">${button('Upload another exam →','startNewExam()','soft')}</div>`:''}`:uploadStep===1?`<form onsubmit="previewUpload(event)"><label for="assessmentTitle">Assessment title</label><input id="assessmentTitle" required maxlength="80" value="${esc(state.assessmentTitle||'Mathematics · Fractions')}"><div class="formgrid"><div><label for="subject">Subject</label><select id="subject"><option>Mathematics</option><option disabled>Science (not in this demo)</option><option disabled>English (not in this demo)</option><option disabled>German (not in this demo)</option></select></div><div><label for="language">Exam language</label><select id="language"><option ${state.language==='English'?'selected':''}>English</option><option ${state.language==='German'?'selected':''}>German</option></select></div></div><label class="drop" for="examfile">${icon('upload')}<h3>Choose your scanned exam</h3><span class="muted">A clear photo or PDF · PNG, JPG, WEBP or PDF · Up to 10 MB</span><input id="examfile" type="file" accept="image/png,image/jpeg,image/webp,application/pdf" onchange="chooseFile(this)"></label><div class="row between" style="margin-top:20px"><button type="button" class="textbtn" onclick="useSample()">Use a sample exam instead</button><button class="btn" type="submit">Preview exam →</button></div></form>`:`<div class="notice">${esc(state.filename)} · ${esc(state.subject)} · ${esc(state.language)}<br>Check that every answer is visible before submitting.</div>${paper()}<div class="row between" style="margin-top:20px">${button('← Choose another file',"resetChosenFile()",'secondary')}${button('Submit to my teacher →',"submitExam()")}</div>`)}
function chooseFile(el){const f=el.files[0];if(!f)return;if(f.size>10*1024*1024||!['image/png','image/jpeg','image/webp','application/pdf'].includes(f.type)){el.value='';toast('Choose a PNG, JPG, WEBP or PDF up to 10 MB.');return}if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl=URL.createObjectURL(f);state.filename=f.name;state.filetype=f.type;toast('File selected. Continue to preview.')}
function useSample(){previewUrl='';state.filename='lina-mathematics-sample.pdf';state.filetype='sample';state.subject=$('#subject').value;state.language=$('#language').value;state.assessmentTitle=$('#assessmentTitle').value.trim();state.answers=sampleAnswers(state.language);Object.assign(state,studentFeedback(state.language));uploadStep=2;render()}
function previewUpload(e){e.preventDefault();if(!state.filename){toast('Choose a file or use the sample exam.');return}state.subject=$('#subject').value;state.language=$('#language').value;state.assessmentTitle=$('#assessmentTitle').value.trim();state.answers=sampleAnswers(state.language);Object.assign(state,studentFeedback(state.language));uploadStep=2;render()}
function resetChosenFile(){if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl='';state.filename='';state.filetype='sample';uploadStep=1;go('upload')}
function submitExam(){state.submitted=true;state.assessmentDate=new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});save();render();toast('Exam submitted. Your teacher can now review it.')}
function startNewExam(){if(state.submitted&&!state.released){toast('Your current exam is still awaiting teacher review.');return}if(state.submitted&&state.released){state.archived.unshift({title:state.assessmentTitle||'Mathematics · Fractions',date:state.assessmentDate||'Earlier assessment',subject:state.subject,language:state.language,marks:[...state.marks],answers:[...state.answers],feedback:state.feedback,practice:state.practice,flag:state.flag,gap:state.gap,filename:state.filename,assessmentId:state.assessmentId,releasedAt:state.releasedAt||Date.parse(state.assessmentDate)||0});}Object.assign(state,{submitted:false,ocr:false,graded:false,released:false,gap:'suggested',flag:'suggested',gapEvidenceReviewed:false,assessmentId:'assessment-'+Date.now()+'-'+Math.floor(Math.random()*100000),marks:[1,5,5],answers:sampleAnswers('English'),filename:'',filetype:'sample',subject:'Mathematics',language:'English',assessmentTitle:'Mathematics · Fractions',assessmentDate:'',releasedAt:0,feedback:initial().feedback,practice:initial().practice});if(previewUrl)URL.revokeObjectURL(previewUrl);previewUrl='';uploadStep=1;save();go('upload');toast('Ready for another assessment. Earlier results are saved.')}

const sampleAnswers=lang=>lang==='German'?['1/8 ist größer als 1/4, weil 8 größer als 4 ist.','3 × 4 = 12','1/2 + 1/2 = 1']:['1/8 is greater than 1/4 because 8 is bigger.','3 × 4 = 12','1/2 + 1/2 = 1'];
const examPrompts=()=>state.language==='German'?['Welcher Bruch ist größer: 1/8 oder 1/4? Begründe deine Antwort.','Berechne 3 × 4.','Berechne 1/2 + 1/2.']:['Which is greater: 1/8 or 1/4? Explain.','Calculate 3 × 4.','Calculate 1/2 + 1/2.'];
const modelAnswers=()=>state.language==='German'?['1/4 ist größer. Bei gleichem Zähler bedeuten weniger gleich große Teile größere Stücke.','3 × 4 = 12','1/2 + 1/2 = 1']:['1/4 is greater. With the same numerator, fewer equal parts means larger pieces.','3 × 4 = 12','1/2 + 1/2 = 1'];
// Rules are intentionally limited to the three fictional sample questions, not general AI grading.
function suggestedMark(i,answer){
 const a=String(answer||'').toLowerCase().replace(/[.,;!?]/g,' ').replace(/\s+/g,' ').trim();
 if(i===0){
  const correct=/1\s*\/\s*4\s*(?:>|ist größer|is greater|is larger|is bigger)/i.test(a);
  const wrong=/1\s*\/\s*8\s*(?:>|ist größer|is greater|is larger|is bigger)/i.test(a);
  return correct&&!wrong?5:wrong?1:0;
 }
 if(i===1)return /^3\s*[×x*]\s*4\s*=\s*12$/.test(a)?5:0;
 if(i===2)return /^(?:1\s*\/\s*2\s*\+\s*1\s*\/\s*2\s*=\s*1|1\s*=\s*1\s*\/\s*2\s*\+\s*1\s*\/\s*2|1)$/.test(a)?5:0;
 return 0;
}
function gradingExplanation(i){
 const suggestion=suggestedMark(i,state.answers[i]);
 if(i===0&&suggestion===1)return state.language==='German'?'Die Begründung vergleicht die Nenner falsch. Beispielvorschlag: 1/5; Teilpunkte durch die Lehrkraft prüfen.':'The reasoning incorrectly compares denominators. Example suggestion: 1/5; the teacher reviews partial credit.';
 return (state.language==='German'?'Beispiel-Regel für die verifizierte Antwort: ':'Sample-rule suggestion for the verified answer: ')+suggestion+'/5. '+(state.language==='German'?'Die Lehrkraft prüft die Antwort und vergibt die Endnote.':'The teacher checks the answer and decides the final mark.');
}
function markEvidenceReviewed(v){state.gapEvidenceReviewed=!!v;save()}
function paper(){if(previewUrl)return state.filetype==='application/pdf'?`<object data="${previewUrl}" type="application/pdf" width="100%" height="420"><a href="${previewUrl}" target="_blank">Open PDF preview</a></object>`:`<div class="paper"><img src="${previewUrl}" alt="Preview of selected exam"></div>`;let ps=examPrompts(),ans=sampleAnswers(state.language);return `<div class="paper"><small>DEMONSTRATION SCAN · SIMULATED OCR</small><h3>${state.language==='German'?'Mathematik · Brüche':'Mathematics · Fractions'}</h3><div>${state.language==='German'?'Lina Mostafa · Klasse 4 · 3 Aufgaben · 15 Punkte':'Lina Mostafa · Grade 4 · 3 questions · 15 marks'}</div>${ps.map((q,i)=>`<p>${i+1}. ${esc(q)}</p><div class="hand">${esc(ans[i])}</div>`).join('')}</div>`}
function queue(){return header('Assessment review','Keep the teacher in control, at every step.')+(state.submitted?card('Lina’s current assessment',steps()+`<div class="row between"><div><h3>${esc(state.subject)} · ${esc(state.language)}</h3><small>${esc(state.filename)} · Lina Mostafa · Grade 4</small></div>${button(state.released?'Review completed assessment':'Continue review →','openReview()')}</div>`):card('Your review queue',`<div class="empty">No new exams yet.<p>Switch to Student view and upload an exam, or start the sample workflow below.</p>${button('Start sample assessment',"startSample()")}</div>`))+card('Previous assessments',examTable())}
function startSample(){state.submitted=true;state.filename='lina-mathematics-sample.pdf';state.filetype='sample';state.assessmentTitle='Mathematics · Fractions';state.assessmentDate=new Date().toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});save();go('ocr')}
function ocr(){if(!state.submitted)return queue();return header('Verify extracted answers','Compare each answer with the original before allowing AI grading.')+steps()+`<div class="notice"><strong>Simulated OCR:</strong> The extracted answers are demonstration data, not automatically read from the uploaded file. The teacher must compare the original paper and every extracted answer before grading.</div><div class="formgrid"><div>${card('Original exam',paper())}</div><div>${card('Extracted text',`<form onsubmit="confirmOCR(event)">${state.answers.map((a,i)=>`<div class="ocrrow ${i===1&&!state.ocr?'warn':''}"><div class="row between"><label for="a${i}">Question ${i+1}</label>${i===1&&!state.ocr?badge('Check extraction','orange'):badge('Review text','gray')}</div><textarea id="a${i}" required>${esc(i===1&&!state.ocr?'3 × 4 = 17':a)}</textarea></div>`).join('')}<div class="notice">The initial sample OCR intentionally misreads “12” as “17” in question 2. Compare all fields with the paper and correct any mismatch before confirming.</div><button class="btn" type="submit">Confirm answers & continue →</button></form>`)}</div></div>`}
function confirmOCR(e){e.preventDefault();state.answers=state.answers.map((_,i)=>$('#a'+i).value);state.ocr=true;state.graded=false;state.released=false;state.marks=state.answers.map((a,i)=>suggestedMark(i,a));state.gapEvidenceReviewed=false;save();go('grading');toast('Extracted text confirmed. Grading suggestions are ready.')}
function grading(){if(!state.ocr)return ocr();return header('Review suggested grades','Check the reasoning. Award partial credit. Make the final decision.')+steps()+card('Question-by-question review',`<form onsubmit="confirmGrades(event)">${state.answers.map((a,i)=>`<div class="question"><div class="row between"><h3>Question ${i+1}</h3>${badge('AI suggestion · Needs your review')}</div><p>${esc(examPrompts()[i])}</p><div class="formgrid"><div><small>VERIFIED STUDENT ANSWER</small><p>${esc(a)}</p></div><div><small>MODEL ANSWER</small><p>${esc(modelAnswers()[i])}</p></div></div><div class="notice">${gradingExplanation(i)}</div><label for="mark${i}">Final teacher mark (out of 5)</label><input id="mark${i}" type="number" min="0" max="5" step="0.5" required value="${state.marks[i]}"></div>`).join('')}<button type="submit" class="btn">Confirm grades & review learning gaps →</button></form>`)}
function confirmGrades(e){e.preventDefault();state.marks=state.marks.map((_,i)=>Number($('#mark'+i).value));state.graded=true;state.released=false;state.gapEvidenceReviewed=false;save();go('gaps');toast('Grades confirmed. Review evidence and feedback before release.')}
function students(){return header('Students','Individual progress, connected to the evidence.')+card('Grade 4 · Class A',`<div class="row between"><div class="row"><div class="avatar">LM</div><div><h3>Lina Mostafa</h3><small>Grade 4 · 1 recurring concept · 2 confirmed quizzes</small></div></div>${button('Open learning profile →',"go('gaps')",'soft')}</div>`)}
function evidence(){return `<div class="timeline"><div class="event"><small>21 OCTOBER 2026 · QUIZ 1 · QUESTION 3</small><h3>First appearance · New</h3><p>Prompt: Which is greater, 1/3 or 1/6?<br><strong>Lina:</strong> “1/6, because 6 is bigger.”<br><strong>Interpretation:</strong> Compares denominator size without considering piece size.</p>${badge('Teacher-confirmed','green')}</div><div class="event"><small>28 OCTOBER 2026 · QUIZ 2 · QUESTION 2</small><h3>The same misconception returns</h3><p>Prompt: Which is greater, 1/2 or 1/5?<br><strong>Lina:</strong> “1/5, because 5 is bigger.”<br><strong>Interpretation:</strong> Same denominator misconception, now linked to Quiz 1.</p>${badge('Teacher-confirmed','green')}</div>${state.graded&&state.gap==='confirmed'?`<div class="event"><small>CURRENT ASSESSMENT · QUESTION 1</small><h3>New evidence linked to the gap</h3><p><strong>Lina:</strong> ${esc(state.answers[0])}<br>Teacher reviewed this suggestion and attached it to the existing concept history.</p>${badge('Teacher-confirmed','green')}</div>`:''}${state.followup?`<div class="event"><small>FOLLOW-UP ASSESSMENT · AFTER INTERVENTION</small><h3>${gapStatus()} · Later evidence</h3><p>${followupEvidence()}</p>${badge('Teacher-confirmed · '+gapStatus(),gapStatus()==='Worsening'?'orange':'green')}</div>`:''}</div>`}
function gaps(){return header('Evidence-based learning gaps','Understand the pattern behind the score.')+`<div class="grid"><div>${card('Comparing fractions',`<div class="row between"><small>Lina Mostafa · Mathematics</small>${badge(gapStatus(),state.followup?'green':'orange')}</div><p class="muted">Misconception: “A larger denominator means a larger fraction.”</p>${evidence()}<details><summary>What supports this conclusion?</summary><p>The earlier two assessments contain the same reasoning error. Only teacher-confirmed evidence contributes to the history. Current AI suggestions remain separate until reviewed.</p></details>`)}${state.graded?card('Review the current AI suggestions',`<h3>Attach the current question to this gap?</h3><p class="muted">Compare the verified answer with the previous evidence before deciding. This is a teacher decision, not automatic validation.</p><div class="notice"><strong>Current verified answer:</strong> ${esc(state.answers[0])}<br><strong>Expected reasoning:</strong> ${esc(modelAnswers()[0])}</div><label class="row" style="align-items:center;gap:8px"><input type="checkbox" style="width:auto" ${state.gapEvidenceReviewed?'checked':''} onchange="markEvidenceReviewed(this.checked)"> I checked this answer against the earlier misconception evidence.</label><div class="row wrap">${button(state.gap==='confirmed'?'✓ Gap confirmed':'Confirm learning gap',"setDecision('gap','confirmed')",state.gap==='confirmed'?'soft':'')}${button(state.gap==='dismissed'?'✓ Suggestion dismissed':'Dismiss suggestion',"setDecision('gap','dismissed')",'secondary')}</div><hr style="border:0;border-top:1px solid #eee;margin:22px 0"><h3>Support flag: repeated fraction misconception</h3><p class="muted">A recommendation to offer support, rather than a label about the child. This decision is independent of confirming the concept evidence.</p><div class="row wrap">${button(state.flag==='confirmed'?'✓ Flag confirmed':'Confirm support flag',"setDecision('flag','confirmed')",state.flag==='confirmed'?'soft':'')}${button(state.flag==='dismissed'?'✓ Flag dismissed':'Dismiss flag',"setDecision('flag','dismissed')",'secondary')}</div>`):''}</div><div>${card('Learning history',`<h3>${gapStatus()} · Comparing fractions</h3><p class="muted">${state.followup?followupEvidence():'First seen 21 October. Repeated in a second assessment on 28 October.'}</p><small>${2+(state.gap==='confirmed'?1:0)+followupCount()} linked teacher-confirmed assessments</small>${statusPanel()}<div style="margin-top:20px">${button('Open support plan →',"go('intervention')",'soft')}</div>`)}${state.graded?card('Personalized feedback & release',`<form onsubmit="releaseResults(event)"><label for="feedback">Feedback to Lina</label><textarea id="feedback" required>${esc(state.feedback)}</textarea><label for="practice">Practice recommendation</label><textarea id="practice" required>${esc(state.practice)}</textarea><div class="notice">Review both the learning-gap suggestion and support flag before publishing. Only released results are visible to the student.</div><button class="btn" type="submit" ${state.gap==='suggested'||state.flag==='suggested'?'disabled':''}>${state.released?'Update released feedback':'Release results & notify student'} →</button></form>`):card('Teacher review first',`<p class="muted">The current exam’s grade and feedback become available here after OCR verification and grade confirmation.</p>${button('Open review queue →',"go('queue')",'soft')}`)}</div></div>`}
function setDecision(key,v){if(key==='gap'&&v==='confirmed'&&!state.gapEvidenceReviewed){toast('Review the verified answer and check the evidence box first.');return}if($('#feedback')){state.feedback=$('#feedback').value;state.practice=$('#practice').value}state[key]=v;save();render();toast(v==='confirmed'?'Teacher decision confirmed.':'AI suggestion dismissed. Historical evidence is preserved.')}
function releaseResults(e){e.preventDefault();if(!state.submitted||!state.ocr||!state.graded||!['confirmed','dismissed'].includes(state.gap)||!['confirmed','dismissed'].includes(state.flag)||(state.gap==='confirmed'&&!state.gapEvidenceReviewed)){toast('Complete OCR verification, grading, and both teacher decisions before releasing results.');return}state.feedback=$('#feedback').value;state.practice=$('#practice').value;const firstRelease=!state.released;state.released=true;if(firstRelease)state.releasedAt=Date.now();const id=state.assessmentId||'assessment-1';let notice=state.notifications.find(n=>n.assessmentId===id);if(!notice){state.notifications.unshift({id:'notice-'+id,assessmentId:id,title:state.assessmentTitle||'Mathematics · Fractions',date:state.assessmentDate||new Date().toLocaleDateString('en-GB'),read:false});}else{notice.title=state.assessmentTitle||notice.title;if(firstRelease)notice.read=false;}save();toast(firstRelease?'Results released. Lina has a new notification.':'Released feedback updated.');render()}
function results(){const current=selected==='current',archived=String(selected).startsWith('archive-'),old=archived?state.archived[Number(String(selected).slice(8))]:null;if(current&&!state.released)return header('Your exam is with your teacher','We’ll let you know when your results are ready.')+card('Assessment status',steps()+`<div class="notice">Your marks and feedback are hidden until your teacher confirms and releases them.</div>${button('Back to my exams',"go('exams')",'secondary')}`);if(archived&&!old)return exams();const idx=Number(selected),marks=current?state.marks:archived?old.marks:null,answers=current?state.answers:archived?old.answers:null,language=current?state.language:archived?old.language:'English',grade=(current||archived)?marks.reduce((a,b)=>a+Number(b),0)+'/15':['10.75/15','9/15','8.25/15'][idx],title=current?state.assessmentTitle:archived?old.title:['Practice 3 · Fractions','Quiz 2 · Fractions','Quiz 1 · Fractions'][idx],feedback=current?state.feedback:archived?old.feedback:'Try drawing the fractions as equal-sized bars. Look at the size of each piece before comparing.',practice=current?state.practice:archived?old.practice:'Draw two fraction bars. Shade 1/3 in one and 1/6 in the other. Which shaded piece is larger?',flag=current?state.flag:archived?old.flag:'confirmed',gap=current?state.gap:archived?old.gap:'confirmed';const prompts=language==='German'?['Welcher Bruch ist größer: 1/8 oder 1/4? Begründe deine Antwort.','Berechne 3 × 4.','Berechne 1/2 + 1/2.']:['Which is greater: 1/8 or 1/4? Explain.','Calculate 3 × 4.','Calculate 1/2 + 1/2.'],models=language==='German'?['1/4 ist größer. Bei gleichem Zähler bedeuten weniger gleich große Teile größere Stücke.','3 × 4 = 12','1/2 + 1/2 = 1']:['1/4 is greater. With the same numerator, fewer equal parts means larger pieces.','3 × 4 = 12','1/2 + 1/2 = 1'];return header('Your assessment feedback',esc(title)+' · Teacher-reviewed results',button('← My exams',"go('exams')",'secondary'))+`<div class="grid"><div>${card('Your teacher-reviewed result',`<div class="row between"><div><div class="score">${grade}</div><small>Mathematics · ${esc(language)} · Teacher-confirmed</small></div>${badge('Results released','green')}</div>${marks?answers.map((a,i)=>`<div class="question"><div class="row between"><h3>Question ${i+1}</h3><strong>${marks[i]}/5</strong></div><p>${esc(prompts[i])}</p><small>YOUR ANSWER</small><p>${esc(a)}</p><div class="notice"><strong>Correct reasoning:</strong> ${esc(models[i])}</div></div>`).join(''):`<div class="question"><h3>Comparing fractions</h3><p>${idx===0?'You are practicing how to compare fractions with pictures. Keep checking that each whole is the same size.':`You chose ${idx===1?'1/5 over 1/2':'1/6 over 1/3'} because the denominator was larger.`}</p><div class="notice">With the same numerator, a larger denominator means smaller equal pieces. Draw two same-sized fraction bars to compare them.</div></div>`}`)}</div><div>${card('Your learning focus',`<h3>Comparing fractions</h3>${badge(gap==='confirmed'?'Teacher-confirmed learning gap':'Practice focus',gap==='confirmed'?'orange':'gray')}<p class="muted">The size of a denominator does not tell you the size of the fraction by itself. Try equal-sized fraction bars.</p>${flag==='confirmed'?`<div class="notice"><strong>Extra teacher support recommended.</strong> Your teacher will help you practice comparing fractions and check your progress.</div>`:''}`)}${card('A note just for you',`<div class="avatar">MS</div><p>${esc(feedback)}</p>`)}${card('Your next small step',`<h3>Practice comparing fractions</h3><p class="muted">${esc(practice)}</p>${button('See my progress →',"go('progress')",'soft')}`)}</div></div>`}

function progress(){return header('Look how far you’ve come','Progress is more than a grade. Every new understanding counts.')+`<div class="grid"><div>${card('My assessment journey',chart())}${card('My fraction journey',`<div class="timeline"><div class="event"><h3>We found a topic to explore</h3><small>Quiz 1 · 21 October</small><p>You began learning how the size of fraction pieces changes.</p></div><div class="event"><h3>Let’s try a different way</h3><small>Quiz 2 · 28 October</small><p>The same idea felt tricky. Your teacher recommended fraction bars.</p></div>${state.followup?`<div class="event"><h3>Let’s see your next step</h3><p>${gapStatus()==='Resolved'?'You compared all five fraction pairs correctly in two later assessments. Well done!':gapStatus()==='Worsening'?'This topic still feels tricky. Your teacher will try another way with you.':'You answered 4 of 5 fraction comparisons correctly in your follow-up. Keep going!'}</p></div>`:''}</div>`)}</div><div>${card('My topics',`<h3>Comparing fractions</h3>${badge(state.followup?(gapStatus()==='Resolved'?'You’ve got this!':gapStatus()==='Worsening'?'Let’s practice together':'Getting better'):'Keep practicing',state.followup?'green':'orange')}<p class="muted">Try pictures to see which fraction is bigger.</p><h3 style="margin-top:25px">Multiplication</h3>${badge('Growing confidence','green')}<p class="muted">Keep practicing your times tables.</p>`)}${state.intervention?card('My practice plan',`<h3>${esc(state.intervention.goal)}</h3><p>${esc(state.intervention.activity)}</p><small>Check-in: ${esc(state.intervention.date)}</small>`):''}</div></div>`}
function notifications(){const items=[...state.notifications].map(n=>`<div class="listitem"><div class="row between"><h3>${esc(n.title)}</h3>${badge(n.read?'Read':'New',n.read?'gray':'green')}</div><p class="muted">${esc(n.date)} · Ms. Sarah has reviewed this assessment and shared feedback.</p>${button('Open my feedback →',`openNotification('${esc(n.id)}')`,'soft')}</div>`).join('');const historic=[...historicalAssessments].reverse().map(x=>`<div class="listitem"><div class="row between"><h3>${esc(x.title)}</h3>${badge('Read','gray')}</div><p class="muted">${esc(x.date)} · Your teacher shared your assessment results.</p>${button('Open my feedback →',`openResult('${x.id}')`,'soft')}</div>`).join('');return header('Your teacher updates','Every released assessment stays in your notification history.')+card('Messages',items+historic||'<div class="empty">No teacher updates yet.</div>')}
function intervention(){return header('Support plans','Turn an evidence-based insight into a practical next step.')+`<div class="grid"><div>${card('Lina’s support plan',`<div class="notice">Linked concept: Comparing fractions · ${gapStatus()}<br>Historical gap supported by two teacher-confirmed quizzes.</div><form onsubmit="savePlan(event)"><label for="goal">Improvement goal</label><input id="goal" required value="${esc(state.intervention?.goal||'Compare unit fractions and explain the size of equal pieces')}"><label for="target">Measurable target: correct comparisons out of 5</label><select id="target">${[3,4,5].map(n=>`<option value="${n}" ${(state.intervention?.target||4)==n?'selected':''}>At least ${n} of 5 comparisons correct</option>`).join('')}</select><label for="activity">Recommended support activity</label><textarea id="activity" required>${esc(state.intervention?.activity||'Use equal-sized fraction bars for 10 minutes, then explain why 1/4 is greater than 1/8.')}</textarea><label for="date">Follow-up date</label><input id="date" type="date" required value="${esc(state.intervention?.date||'2026-11-12')}"><label for="completed"><input id="completed" type="checkbox" style="width:auto;margin-right:8px" ${state.intervention?.completed?'checked':''}> Support activity completed</label><button class="btn" type="submit">${state.intervention?'Save plan changes':'Save support plan'}</button></form>`)}${state.intervention?card('Follow-up review',state.followup?`<div class="row between"><h3>${gapStatus()==='Resolved'?'5 out of 5 correct in two later assessments':gapStatus()==='Worsening'?'1 out of 5 comparisons correct':'4 out of 5 comparisons correct'}</h3>${badge((gapStatus()==='Worsening'||(gapStatus()==='Improving'&&(state.intervention?.target||4)>4))?'Further practice needed':'Target met',(gapStatus()==='Worsening'||(gapStatus()==='Improving'&&(state.intervention?.target||4)>4))?'orange':'green')}</div><p class="muted">${followupEvidence()}</p><div class="notice"><strong>Measurable check:</strong> ${followupScore()}/5 correct · Target: ${state.intervention.target}/5 · ${followupScore()>=state.intervention.target?'Target reached':'Target not reached'}. A successful outcome cannot be recorded if the target is unmet.</div><label for="outcome">Teacher’s intervention outcome</label><select id="outcome">${['Ongoing','Successful','Requires further support'].map(v=>`<option ${state.outcome===v?'selected':''}>${v}</option>`).join('')}</select><label for="outcomenote">Outcome notes</label><textarea id="outcomenote">${esc(state.outcomenote||(followupScore()>=state.intervention.target?'Target reached in this fictional follow-up. Recheck consistency in the next assessment.':'The measurable target is not yet reached. Continue practice and reassess.'))}</textarea><div style="margin-top:17px">${button('Record outcome',"recordOutcome()")}</div>`:`<p class="muted">Complete the support activity, then choose a clearly labelled example of later assessment evidence.</p>${statusPanel()}${!state.intervention.completed?'<p><small>Mark the activity completed and save the plan to continue.</small></p>':''}`):''}</div><div>${card('Why this plan?',`<h3>Evidence, then action</h3><p class="muted">Quiz 1 and Quiz 2 show the same denominator-size misconception. Fraction bars give Lina a concrete way to compare equal parts.</p>${button('Open evidence timeline →',"go('gaps')",'soft')}`)}${state.intervention?card('Plan status',`${badge(state.outcome,state.outcome==='Successful'?'green':'orange')}<p class="muted">Follow-up: ${esc(state.intervention.date)}</p><small>${state.intervention.completed?'✓ Support activity completed':'Support activity not yet completed'}</small>`):''}</div></div>`}
function savePlan(e){e.preventDefault();const previousGoal=state.intervention?.goal||'';state.intervention={goal:$('#goal').value,target:Number($('#target').value),activity:$('#activity').value,date:$('#date').value,completed:$('#completed').checked};if(state.outcome==='Successful'&&(previousGoal.trim()!==state.intervention.goal.trim()||!state.intervention.completed||!state.followup||followupScore()<state.intervention.target)){state.outcome='Ongoing';state.outcomenote='';toast('Goal changed. Recheck the outcome against the new target.')}save();render();toast('Support plan saved.')}
function loadFollowup(){state.followup=true;state.followupReviewedAt=Date.now();save();render();toast('Sample follow-up reviewed and confirmed. Gap status: improving.')}
function followupScore(){return gapStatus()==='Resolved'?5:gapStatus()==='Worsening'?1:4}
function recordOutcome(){if(!state.intervention?.completed||!state.followup){toast('Complete the support activity and review follow-up evidence first.');return}const proposed=$('#outcome').value,target=Number(state.intervention?.target||4);if(proposed==='Requires further support'&&gapStatus()==='Resolved'){toast('The reviewed follow-up shows the learning gap resolved. Choose Ongoing or Successful.');return}if(proposed==='Successful'&&followupScore()<target){toast('Target not met: '+followupScore()+'/5 correct, but the goal is '+target+'/5. Choose Ongoing or Requires further support.');return}state.outcome=proposed;state.outcomenote=$('#outcomenote').value;save();render();toast('Intervention outcome recorded.')}

const tasks=[["Student views exam results and personalized feedback",["Open Student overview and click My exams.","Choose a teacher-released assessment. If pending, read its review status and stop.","Read the displayed final grade, question-level marks, and corrected answers.","Read the teacher-approved feedback and topic needing practice.","Read the recommended practice; click See my progress if desired."],"Do 1–4 in order. Do 5 when a recommendation is available."],["Teacher verifies OCR-extracted answers",["Open Assessment review to access the current submitted exam.","Compare each original paper answer with its extracted text.","Edit any mismatched OCR text; repeat for all three questions.","Click Confirm answers & continue to unlock grade review."],"Repeat 2–3 until the extracted answers are checked; then do 4."],["Teacher reviews and tracks evidence-based learning gaps",["Open Students → Open learning profile, or Learning gaps.","Select Comparing fractions and read the linked questions and answers.","Compare the recurring misconception across the assessment timeline.","Tick the evidence-review acknowledgement checkbox after inspecting the evidence.","Confirm or dismiss the current learning-gap suggestion; separately review the support flag.","Read the updated evidence count and recurring/improving status."],"Do 1–3, then acknowledge reviewed evidence in 4 before 5. Review the support flag separately. Confirming adds the current evidence; dismissing preserves previously confirmed evidence. Then do 6."],["Teacher plans and tracks learning-gap support plans",["From Learning gaps, click Open support plan.","Enter an improvement goal, measurable target, and recommended support activity.","Set a follow-up date and click Save support plan.","After the activity, check Support activity completed and click Save plan changes.","Review sample follow-up evidence and compare it with the measurable target.","Choose Ongoing, Successful, or Requires further support; enter notes and click Record outcome."],"Do 1–3 to create the plan. At follow-up, do 4–6 in order."],["Teacher reviews and confirms AI grades",["Open Assessment review after OCR text is confirmed.","Compare each verified student answer with its model answer and AI explanation.","Adjust the Final teacher mark field if the rubric requires a different score.","Repeat for every question; click Confirm grades & review learning gaps.","Review learning-gap and support-flag evidence and decisions; edit teacher feedback, then click Release results & notify student after all required reviews."],"Repeat 2–3 for all questions before 4. Then complete the teacher decisions and feedback in 5 before releasing results; grades remain hidden until release."],["Student uploads an exam",["Click Upload an exam in Student view.","Enter the assessment title; choose Mathematics and the exam language (English or German).","Choose a supported image/PDF up to 10 MB, or Use a sample exam.","Click Preview exam and check the paper. If incorrect, click Choose another file and repeat 3–4.","Click Submit to my teacher.","Read the teacher-review status; return to My exams to check for released results."],"Do 1–4 in order, including entering the assessment title. Correct an unsuitable file before 5. Then do 6."]];
function guide(){return header('Help & support','A connected demonstration of your Milestone 1 and 2 design.')+card('Start here',`<p>This is an interactive frontend prototype with fictional assessment data. AI extraction, grading and historical matching are simulated. Teacher edits, approvals, feedback, notifications and plans are saved in this browser.</p><div class="row wrap">${button('Start with student upload',"switchRole('student');go('upload')")}${button('Reset example workspace',"resetDemo()",'secondary')}${button('Download source package',"location.href='uxplosion-milestone3-source.zip'",'soft')}</div><p class="muted">Uploaded file previews are session-only and are never sent to a server. After refresh, the teacher sees the labelled sample scan; stored metadata and decisions remain. Student and teacher switching is a demonstration control, not authentication.</p>`)+card('Hierarchical task designs',tasks.map((t,i)=>`<article class="htd"><h3>0. ${i+1} · ${t[0]}</h3><ol>${t[1].map(s=>`<li>${s}</li>`).join('')}</ol><div class="notice"><strong>Plan 0:</strong> ${t[2]}</div></article>`).join(''))}

function gapStatus(){return state.followup?(state.followupScenario||'Improving'):'Recurring'}
function followupCount(){return state.followup?(gapStatus()==='Resolved'?2:1):0}
function followupEvidence(){return gapStatus()==='Resolved'?'Two separate later sample assessments each show 5 of 5 correct fraction comparisons, with correct explanations of equal piece size. The teacher confirmed both assessments; this supports marking the misconception resolved.':gapStatus()==='Worsening'?'The later sample assessment shows only 1 of 5 comparisons correct. The denominator misconception appears in four answers, compared with two errors in the earlier sample. The teacher confirms that further support is needed.':'The later sample assessment shows 4 of 5 comparisons correct and a 90% overall score. Lina explains equal piece size correctly. The gap is improving; one error remains, so it is not marked resolved.'}
function statusPanel(){if(!state.intervention?.completed||state.followup)return '';return `<div class="notice"><strong>Explore a later evidence scenario</strong><p>Each scenario loads clearly labelled sample work and requires teacher confirmation. It replaces the previous follow-up example.</p><label for="scenario">Sample follow-up evidence</label><select id="scenario">${['Improving','Worsening','Resolved'].map(v=>`<option ${gapStatus()===v?'selected':''}>${v}</option>`).join('')}</select><button class="btn soft" style="margin-top:12px" onclick="confirmScenario()">Review & confirm sample evidence</button></div>`}
function confirmScenario(){const scenario=$('#scenario').value;if(!confirm('Use the '+scenario.toLowerCase()+' fictional follow-up example as teacher-confirmed evidence?'))return;state.followupScenario=scenario;state.followup=true;state.followupReviewedAt=Date.now();state.outcome='Ongoing';state.outcomenote='';save();render();toast('Fictional follow-up evidence reviewed. Learning gap: '+gapStatus()+'.')}

function resetDemo(){if(!confirm('Reset all prototype progress, reviews, and plans in this browser?'))return;state=initial();previewUrl='';uploadStep=1;save();go('dashboard');toast('Demo reset. Ready to start again.')}
render();
